import { Crossword } from "@hunt/puzzle-components";
import React, { type CSSProperties } from "react";
import "./font.css";

const GRID_SIZE = 11;

const FILL: string[][] = [
  ["g", "i", "a", "n", "t", "r", "a", "n", "s", "o", "m"],
  ["a", "c", "t", "e", "d", "i", "n", "c", "a", "n", "p"],
  ["m", "e", "t", "r", "i", "c", "t", "o", "r", "c", "h"],
  ["b", "r", "i", "o", "n", "e", "g", "v", "i", "e", "a"],
  ["l", "u", "c", "k", "i", "s", "l", "e", "e", "b", "b"],
  ["i", "n", "f", "a", "n", "t", "u", "n", "l", "i", "u"],
  ["n", "e", "a", "r", "g", "a", "e", "l", "i", "c", "n"],
  ["g", "e", "t", "s", "u", "r", "v", "e", "y", "e", "d"],
  ["a", "s", "h", "e", "n", "o", "i", "r", "u", "s", "a"],
  ["u", "p", "o", "o", "d", "l", "e", "o", "m", "e", "n"],
  ["g", "y", "m", "n", "a", "m", "w", "y", "a", "t", "t"],
];

const VERTICAL_BARS: number[][] = [
  [4],
  [4, 9],
  [5],
  [3, 6, 9],
  [3, 7],
  [5, 7],
  [3, 9],
  [2],
  [3, 7],
  [0, 6],
  [2, 5],
];

const HORIZONTAL_BARS: number[][] = [
  [4, 7],
  [],
  [1, 6, 10],
  [3, 5, 8, 9],
  [2],
  [7],
  [1, 4, 6, 8],
  [0, 3, 5, 9],
  [],
  [4],
];

const HIGHLIGHTS: string[][] = [
  [".", ".", ".", ".", ".", "Y", ".", ".", "Y", "Y", "."],
  [".", "Y", ".", "Y", ".", ".", ".", "Y", ".", ".", "."],
  [".", "Y", ".", "Y", ".", "Y", ".", "Y", "Y", "Y", "."],
  [".", "Y", ".", "Y", ".", "Y", ".", ".", ".", "Y", "."],
  [".", ".", "Y", ".", ".", "Y", ".", "Y", "Y", ".", "."],
  [".", ".", ".", ".", ".", ".", ".", ".", ".", ".", "."],
  [".", "Y", ".", "Y", ".", ".", "Y", ".", ".", "Y", "."],
  [".", "Y", ".", "Y", ".", "Y", ".", "Y", ".", "Y", "."],
  [".", "Y", ".", "Y", ".", "Y", ".", "Y", ".", "Y", "."],
  [".", ".", "Y", "Y", ".", ".", "Y", "Y", ".", "Y", "."],
  [".", ".", ".", ".", ".", ".", ".", ".", ".", ".", "."],
];

const EMPTY_LABELS: string[][] = Array.from({ length: GRID_SIZE }, () =>
  Array.from({ length: GRID_SIZE }, () => ""),
);

function getGridBarClasses(row: number, column: number): string[] {
  const classes: string[] = [];

  if (row === GRID_SIZE - 1 || HORIZONTAL_BARS[row]?.includes(column)) {
    classes.push("border-b-4");
  } else {
    classes.push("border-b");
  }

  if (row === 0) {
    classes.push("border-t-4");
  } else {
    classes.push("border-t");
  }

  if (column === GRID_SIZE - 1 || VERTICAL_BARS[row]?.includes(column)) {
    classes.push("border-r-4");
  } else {
    classes.push("border-r");
  }

  if (column === 0) {
    classes.push("border-l-4");
  } else {
    classes.push("border-l");
  }

  classes.push("text-lg", "font-semibold", "charfont");

  return classes;
}

const getAdditionalCellStyles = ({
  row,
  column,
}: {
  row: number;
  column: number;
}): CSSProperties => {
  return {
    backgroundColor: HIGHLIGHTS[row][column] === "Y" ? "#0d5200" : "",
    color: HIGHLIGHTS[row][column] === "Y" ? "#fff" : "",
  };
};

const getAdditionalCellClass = ({
  row,
  column,
}: {
  row: number;
  column: number;
}) => getGridBarClasses(row, column).join(" ");

export const PeacefulSlipSolutionGrid: React.FC = () => {
  return (
    <Crossword
      labels={EMPTY_LABELS}
      fill={FILL}
      getAdditionalCellClass={getAdditionalCellClass}
      getAdditionalCellStyles={getAdditionalCellStyles}
      className="mx-auto"
    />
  );
};
